from math import gcd

def verifier(assign):
    # Extract and validate inputs
    try:
        N = int(assign.get('n_points'))
        d = int(assign.get('dimension'))
        s_num = int(assign.get('total_second_moment_num'))
        s_den = int(assign.get('total_second_moment_den'))
        t_num = int(assign.get('sum_vector_sqnorm_num'))
        t_den = int(assign.get('sum_vector_sqnorm_den'))
    except Exception:
        return (False, None)  # invalid types
    # Basic domain checks
    if d < 2 or N <= 0:
        return (False, None)
    if s_den <= 0 or t_den <= 0:
        return (False, None)
    # Ensure N is a multiple of (d+1) to guarantee achievability via repeated regular d-simplices
    if N % (d + 1) != 0:
        return (False, None)
    # Reduce input fractions
    g1 = gcd(abs(s_num), s_den)
    s_num_r = s_num // g1
    s_den_r = s_den // g1
    g2 = gcd(abs(t_num), t_den)
    t_num_r = t_num // g2
    t_den_r = t_den // g2
    # Feasibility: T <= N*S and T >= 0
    # Compare T and N*S by cross-multiplying: T <= N*S  <=>  t_num_r * s_den_r <= N * s_num_r * t_den_r
    if t_num_r < 0:
        return (False, None)
    if t_num_r * s_den_r > N * s_num_r * t_den_r:
        return (False, None)
    # Compute R = N*S - T as a rational: R = num_R / den_R > 0
    num_R = N * s_num_r * t_den_r - t_num_r * s_den_r
    den_R = s_den_r * t_den_r
    if num_R <= 0:
        return (False, None)
    # The exact minimal diameter D_min follows from Jung's theorem in R^d:
    # J_d^2 = d / (2(d+1)), hence 1/J_d^2 = 2(d+1)/d.
    # D_min^2 = (1 / (N^2 * J_d^2)) * (N*S - T) = (2(d+1)/d) * (num_R/den_R) / N^2
    # => D_min^2 = [2(d+1)*num_R] / [d * N^2 * den_R]
    num = 2 * (d + 1) * num_R
    den = d * (N ** 2) * den_R
    # Reduce the fraction under the square root
    g = gcd(num, den)
    num //= g
    den //= g
    # Construct LaTeX-like exact answer string
    if den == 1:
        ans_str = f"\\sqrt{{{num}}}"
    else:
        ans_str = f"\\sqrt{{{num}/{den}}}"
    # Provide a sanity numeric check (not used for acceptance but to ensure finite values)
    try:
        approx = (num / den) ** 0.5
        if not isfinite(approx) or approx <= 0:
            return (False, None)
    except Exception:
        return (False, None)
    return (True, ans_str)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

